    return re.sub(r'\s+',' ',s.replace('│',' '))
n=norm(src)
d=yaml.safe_load(open('.coordination/mining/v2/day-015.yaml'))
bad=[]
def check(q,where):
    for part in [p for p in q.split('\n') if p.strip()]:
        p=norm(part).strip()
        if p not in n: bad.append((where,p[:80]))
for sec in ['philosophy','skill_rules','pairing_rules']:
    for it in d[sec]:
        if it.get('quote'): check(it['quote'], it.get('rule_id') or it['statement'][:30])
for f in d['failure_modes']: check(f['quote'], f['name']+' '+f['loc'])
